import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Challenges & Rewards","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/dungeon/challenges.md","filePath":"en/modules/dungeon/challenges.md","lastUpdated":0}`),a={name:`en/modules/dungeon/challenges.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="challenges-rewards" tabindex="-1">Challenges &amp; Rewards <a class="header-anchor" href="#challenges-rewards" aria-label="Permalink to “Challenges &amp; Rewards”">​</a></h1><p>The full player loop covers how a run starts, how limits are counted, how rewards are paid, and what happens when you fail</p><h2 id="entry-flow" tabindex="-1">Entry flow <a class="header-anchor" href="#entry-flow" aria-label="Permalink to “Entry flow”">​</a></h2><ol><li><strong>Start</strong>: first run <code>/edg list</code> to see available dungeons, then <code>/edg enter &lt;dungeonId&gt;</code> to start a challenge (<strong>leader only</strong> while in a party)</li><li><strong>Pre-checks</strong>: the plugin checks dungeon existence, entry permission (<code>emakidungeon.dungeon.&lt;dungeonId&gt;</code>), party state, capacity, and limits (cooldown, then day, week, month, and time window); the first failing check explains why</li><li><strong>Difficulty</strong>: a &quot;select difficulty&quot; panel opens and offers the tiers configured under the dungeon&#39;s <code>difficulty</code></li><li><strong>Drop mode</strong>: a &quot;select drop distribution mode&quot; panel opens with the modes from <code>drop.mode-allowed</code></li><li><strong>Ready confirmation</strong>: every member confirms with <code>/edg ready</code> or the confirmation button within <code>enter.prepare-window-seconds</code>; timing out cancels the challenge</li><li><strong>World preparation</strong>: the plugin clones the template world and shows progress on <code>enter.wait-channel</code> (bossbar / scoreboard / chat); any member can <code>/edg cancel</code>, and waiting longer than <code>enter.wait-timeout-seconds</code> cancels automatically</li><li><strong>Entry</strong>: the party is assigned a pooled world and teleported in, <strong>the daily count is charged</strong>, and a snapshot is taken at that moment for later rollback</li></ol><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Starting requires every member online - a single offline member refuses the start; a party can only have one active challenge at a time</p></div><h2 id="entry-limits" tabindex="-1">Entry limits <a class="header-anchor" href="#entry-limits" aria-label="Permalink to “Entry limits”">​</a></h2><p>Each dungeon keeps its own <code>limits</code>, always evaluated as <strong>month &gt; week &gt; day</strong>:</p><ul><li><code>count: 0</code> means unlimited for that tier; failing any tier (exhausted count, wrong weekday, wrong week-of-month, or outside the time window) refuses entry and shows how long until the next chance</li><li><code>cooldown-seconds</code> is a hard cooldown between entries and is evaluated on its own</li><li>Counts bucket per day using <code>general.timezone</code>, falling back to the server timezone</li><li>Check your day/week/month usage, cooldown, and best result with <code>/edg stats [player] [dungeonId]</code></li><li>OPs and players holding <code>emakidungeon.bypass.limit</code> ignore all counts and cooldowns</li></ul><h2 id="party-rules" tabindex="-1">Party rules <a class="header-anchor" href="#party-rules" aria-label="Permalink to “Party rules”">​</a></h2><ul><li>Party size is capped by <code>party.max-size</code>; joining behavior follows <code>party.invite-mode</code> (<code>public</code> direct join / <code>apply</code> application pending approval / <code>invite</code> invite only)</li><li><strong>Only the leader</strong> can start a challenge and pick difficulty and drop mode; the start is refused while any member is offline</li><li>A party that is already in a run does not accept new members and cannot start a second challenge</li><li>The party channel (<code>/edg party chat</code>) keeps your messages among teammates; dungeon chat stays inside the instance by default, <code>/edg globalchat on</code> bridges it back to the whole server</li></ul><p>Command and permission details are on <a href="./commands.html#party-subcommands">Commands</a></p><h2 id="in-run-rewards-and-settlement" tabindex="-1">In-run rewards and settlement <a class="header-anchor" href="#in-run-rewards-and-settlement" aria-label="Permalink to “In-run rewards and settlement”">​</a></h2><ul><li><strong>Routed rewards go to your stash first</strong>: loot handled by the distribution modes (roll / contribution pool / share) and items granted by the flow land in your stash with a &quot;stored for this run, paid on clear&quot; message; dungeon reward chests stay <strong>locked until settlement</strong></li><li><strong>Only a clear pays out</strong>: on completion the stash is paid out, then <code>settlement.commands</code> runs line by line (handy for EmakiItem/EmakiLevel items and experience)</li><li>The five modes (<code>drop.default-mode</code> / <code>drop.mode-allowed</code>) decide what monster drops do: <ul><li><code>free</code> vanilla drops: not intercepted, whoever picks it up keeps it (default)</li><li><code>roll</code> drops are rolled automatically and the winner&#39;s share goes to their stash, paid on clear</li><li><code>killer</code> drops go to the killer</li><li><code>score</code> drops enter the contribution pool, distributed by score weight on settlement (<code>drop.levels</code> applies)</li><li><code>share</code> drops are split across the party</li></ul></li><li>Payout is announced as &quot;N items paid from your stash&quot;; with the reward box enabled they land in the box, otherwise in the inventory</li><li>Drop amounts scale with <code>difficulty.&lt;tier&gt;.drop-multiplier</code>, and waves marked as no-drop produce nothing</li></ul><h2 id="reward-box-and-claiming" tabindex="-1">Reward box and claiming <a class="header-anchor" href="#reward-box-and-claiming" aria-label="Permalink to “Reward box and claiming”">​</a></h2><p>With <code>rewardbox.enabled: true</code> (default), clear payouts go to your <strong>personal reward box</strong>, and chat shows a clickable <code>/edg rewards</code> hint:</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><code>/edg rewards</code></td><td>Open the reward box; drag items into your inventory to claim them</td></tr><tr><td>Click &quot;previous / next page&quot;</td><td>Flip pages; the base page count comes from <code>default-pages</code> in <code>gui/rewardbox.yml</code></td></tr><tr><td>Click &quot;auto-flow&quot;</td><td>On: later rewards go straight to your inventory (they still land in the box if your inventory is full); off: rewards keep accumulating in the box for manual pickup</td></tr></tbody></table><p>Capacity rules (<code>capacity-slots</code> in <code>gui/rewardbox.yml</code>, default 135 slots):</p><ul><li>A <strong>full box refuses claims</strong>; items stay inside until you free up space</li><li>Rolls <strong>skip players whose box is full</strong></li><li>When everyone&#39;s box is full, the batch <strong>falls to the ground as collectible drops</strong></li><li>With <code>rewardbox.enabled: false</code> the whole feature is off: payouts go straight to the inventory, falling to the ground when it is full</li></ul><h2 id="failure-leaving-and-rollback" tabindex="-1">Failure, leaving, and rollback <a class="header-anchor" href="#failure-leaving-and-rollback" aria-label="Permalink to “Failure, leaving, and rollback”">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>Voluntary exit (<code>/edg leave</code>)</td><td>Type <code>confirm</code> in chat to proceed; inventory and state roll back to the entry snapshot and you return to your origin; <strong>the whole run stash is voided</strong></td></tr><tr><td>Failure / all players dead / timeout destroy</td><td>Same void: stashed items, experience, and other outputs are wiped, the player snapshot is restored, and you are sent back</td></tr><tr><td>Reconnect</td><td>Reconnecting returns you into the running instance; if the instance is already gone, the snapshot is restored with a notice</td></tr><tr><td>Instance lost to a plugin fault</td><td>Orphan snapshots restore inventory and state from the entry snapshot automatically</td></tr></tbody></table><p>In short: <strong>you only keep rewards by clearing</strong>; leaving early costs whatever the run produced</p><h2 id="spectation-and-survival" tabindex="-1">Spectation and survival <a class="header-anchor" href="#spectation-and-survival" aria-label="Permalink to “Spectation and survival”">​</a></h2><ul><li>Each death consumes <code>difficulty.&lt;tier&gt;.respawn-count</code>; every death broadcasts the remaining count</li><li>At zero respawns the player moves to <strong>spectation</strong>: view rotation only, <strong>no free flight</strong>, unlocked automatically when leaving the dungeon</li><li>Crossing the dungeon boundary pulls you back to the spawn point (<code>guard.boundary_pullback</code>)</li><li>The flow can grant <code>temp_items</code> temporary items: a message appears when your inventory is too full to receive them, and the instance takes them back automatically when the run ends</li></ul><h2 id="scoring-and-leaderboard" tabindex="-1">Scoring and leaderboard <a class="header-anchor" href="#scoring-and-leaderboard" aria-label="Permalink to “Scoring and leaderboard”">​</a></h2><ul><li>The run score combines the five <code>score</code> weights (damage, kills, heal, deaths, defense), capped by <code>score.max</code></li><li>Run <code>/edg rank &lt;dungeonId&gt;</code> to see the dungeon&#39;s top 10 (score, duration, difficulty, party); retention is controlled by <code>leaderboard.max-entries</code></li><li>Countdown reminders are pushed at the <code>timer.messages</code> marks</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};